                    } else {
                        $whitespaceContent = $whitespaceToken->getContent();
                        $pregMatches = [];
                        $pregResult = @preg_match($utf8WhitespacePattern, $whitespaceContent, $pregMatches, 0, 0);
                        $pregError = preg_last_error();
                        $pregSucceeded = false !== $pregResult && PREG_NO_ERROR === $pregError;

                        if (!$pregSucceeded) {
