{
    $this->alternativeSyntaxAnalyzer = new AlternativeSyntaxAnalyzer();

    $blockSignatureFirstTokens = [
        T_USE,
        T_IF,
        T_ELSE,
        T_ELSEIF,
        T_FOR,
        T_FOREACH,
        T_WHILE,
        T_SWITCH,
        T_CASE,
        T_DEFAULT,
        T_TRY,
        T_CLASS,
        T_INTERFACE,
        T_TRAIT,
        T_EXTENDS,
        T_IMPLEMENTS,
    ];
